set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
root=/var/lib/news-flow/qc-complete27-20261122
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {NewsHttpDriver,NewsProxyPool} from './src/newsFlow/transport.mjs';import {NewsNetworkPool} from './src/newsFlow/networkPool.mjs';const root='/var/lib/news-flow/qc-complete27-20261122',r=JSON.parse(fs.readFileSync(root+'/qualified-sites.json')),s=r.sites.find(s=>s.site==='molistar.com'),registry=await loadNewsRegistry(),pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),network=new NewsNetworkPool({workers:1}),report={at:new Date().toISOString(),proxyCount:pool.proxies.length,checks:[]},url=s.pages.find(p=>p.doc).url;
try{for(const proxy of pool.proxies.slice(0,6)){const fixed=Object.create(pool);fixed.choose=()=>proxy;const driver=new NewsHttpDriver({state:{cacheResponses:false,failedUrl:()=>false,request:()=>null,reserve:()=>true,cache:()=>null,completeHttpResponse:()=>{}},pool:fixed,network,allowedDomains:registry.allowedDomains,profiles:{...JSON.parse(r.profilesText),[s.site]:s.profile},siteCooldown:false,maxWireRequests:3}),check=async(target,phase)=>{const p=await driver.get('qc27-moli-proxy-'+proxy.id+'-'+phase,target,s.config,[],{reviewFailed:true,taskRole:'review'}),o={proxyId:proxy.id,url:target,phase,error:p.error,statusCode:p.statusCode,cookieNames:driver.cookies.header(target).split(';').map(x=>x.trim().split('=')[0]).filter(Boolean)};if(!p.error&&p.html){o.file=root+'/evidence/'+createHash('sha256').update(p.html).digest('hex')+'.gz';fs.writeFileSync(o.file,gzipSync(p.html));}report.checks.push(o);console.log(JSON.stringify(o));return p;};const first=await check(url,'cold-article');if(first.error){await check(s.seeds[0].url,'public-homepage');await check(url,'after-homepage');}}
fs.writeFileSync(root+'/molistar-proxy-controls.json',JSON.stringify(report,null,2));console.log(JSON.stringify({proxyCount:pool.proxies.length}));}finally{await network.close();}
NODE
install -o "$SUDO_USER" -m 0600 "$root/molistar-proxy-controls.json" "$upload_dir/.qc27-complete-molistar-proxy.json"
